// Auto-generated server-only PNG assets for Official Relieving & Experience Letters.
// Bundled directly into server code so production/Vercel serverless functions never
// depend on runtime filesystem lookups against public/ or local workspace paths.
// SECURITY: Never import this file at top-level in client routes or *.functions.ts.

export const RELIEVING_ASSET_DIMENSIONS = {
  header: { width: 1024, height: 306 },
  footer: { width: 1024, height: 119 },
  stamp: { width: 192, height: 219 },
} as const;

const HEADER_BANNER_BASE64 = "";

const FOOTER_BANNER_BASE64 = "";

const OFFICIAL_SIGNATURE_STAMP_BASE64 = "";

function decodeBase64(b64: string): Uint8Array {
  return new Uint8Array(Buffer.from(b64, "base64"));
}

export function getRelievingHeaderPng(): Uint8Array {
  return decodeBase64(HEADER_BANNER_BASE64);
}

export function getRelievingFooterPng(): Uint8Array {
  return decodeBase64(FOOTER_BANNER_BASE64);
}

export function getRelievingSignatureStampPng(): Uint8Array {
  return decodeBase64(OFFICIAL_SIGNATURE_STAMP_BASE64);
}

export function getRelievingSignatureStampDataUri(): string {
  return `data:image/png;base64,${OFFICIAL_SIGNATURE_STAMP_BASE64}`;
}
